/**
 * The configured menus as Nuxt UI items (ADR-015). A section becomes a group, its label
 * a `type: 'label'` item; `to` becomes a route, `action` an `onSelect`, an item without
 * either opens the layout's placeholder route. The active item is the one the deepest
 * route names in `meta.menu`, or else the one whose `to` is a matched route; its parent
 * is open, and the open parent follows navigation. Generated by forge.
 */
import { computed, inject, provide, ref, watch, type ComputedRef, type InjectionKey, type Ref } from 'vue'
import { useRoute, useRouter, type RouteLocationNormalizedLoaded } from 'vue-router'
import type { DropdownMenuItem, NavigationMenuItem } from '@nuxt/ui'
import { application } from './config'
import { runAction } from './context'
import type { ApplicationConfig, LayoutConfig, MenuItemConfig, MenuName } from './contracts'

export type MenuBadges = Record<string, number | string | null | undefined>

type MatchedRoute = Pick<RouteLocationNormalizedLoaded, 'matched'>

const BADGES: InjectionKey<Ref<MenuBadges>> = Symbol('application-menu-badges')

/** Supply the values of the badge keys the menus name; call it in the layout wrapper or App. */
export function provideMenuBadges(values: Ref<MenuBadges>): void {
  provide(BADGES, values)
}

/** The id in the deepest matched route's `meta.menu`, or null. */
export function activeMenuItem(route: MatchedRoute): string | null {
  for (let i = route.matched.length - 1; i >= 0; i -= 1) {
    const id = route.matched[i]?.meta?.menu
    if (typeof id === 'string' && id) return id
  }
  return null
}

function allItems(layout: LayoutConfig): MenuItemConfig[] {
  const flat = (items: MenuItemConfig[]): MenuItemConfig[] => items.flatMap(item => [item, ...flat(item.children ?? [])])
  return Object.values(layout.menus).flatMap(sections => flat(sections.flatMap(section => section.items)))
}

/** The active item of a layout: the route's `meta.menu`, else the item whose `to` is the deepest matched route. */
export function resolveActiveItem(layout: LayoutConfig, route: MatchedRoute): string | null {
  const named = activeMenuItem(route)
  if (named) return named
  const items = allItems(layout)
  for (let i = route.matched.length - 1; i >= 0; i -= 1) {
    const name = route.matched[i]?.name
    const item = typeof name === 'string' ? items.find(candidate => candidate.to === name) : undefined
    if (item) return item.id
  }
  return null
}

function contains(item: MenuItemConfig, id: string | null): boolean {
  return id !== null && (item.id === id || (item.children ?? []).some(child => contains(child, id)))
}

/** The parents holding the item `id` in one menu. */
function parentsOf(layout: LayoutConfig, menu: MenuName, id: string | null): string[] {
  return layout.menus[menu]
    .flatMap(section => section.items)
    .filter(item => item.children?.length && item.id !== id && contains(item, id))
    .map(item => item.id)
}

interface BuildOptions {
  active?: string | null
  badges?: MenuBadges
  application?: ApplicationConfig
  /** Whether the layout's placeholder route takes the item id as `:item`. */
  placeholderTakesItem?: boolean
}

/** The items of one menu of one layout, grouped by section. */
export function buildMenu(
  layout: string,
  menu: MenuName,
  { active = null, badges = {}, application: app = application, placeholderTakesItem = true }: BuildOptions = {},
): NavigationMenuItem[][] {
  const config = app.layouts[layout]
  if (!config) throw new Error(`Unknown layout '${layout}'.`)

  function toItem(item: MenuItemConfig): NavigationMenuItem {
    const result: NavigationMenuItem = { label: item.label, value: item.id }
    if (item.icon) result.icon = item.icon
    const badge = item.badge ? badges[item.badge] : undefined
    if (badge !== undefined && badge !== null && badge !== '') result.badge = badge
    if (item.children?.length) {
      result.children = item.children.map(toItem)
      result.defaultOpen = contains(item, active)
      return result
    }
    if (item.action) {
      const action = item.action
      result.onSelect = () => {
        runAction(action)
      }
      return result
    }
    if (item.to) result.to = { name: item.to }
    else if (config!.placeholder) {
      result.to = placeholderTakesItem ? { name: config!.placeholder, params: { item: item.id } } : { name: config!.placeholder }
    }
    else result.disabled = true
    // The resolved active item wins over link matching, so one item is active.
    if (active !== null) result.active = item.id === active
    return result
  }

  return config.menus[menu].map(section => [
    ...(section.label ? [{ type: 'label' as const, label: section.label }] : []),
    ...section.items.map(toItem),
  ])
}

/** One menu of one layout, following the current route and the badges provided. */
export function useApplicationMenu(layout: string, menu: MenuName): ComputedRef<NavigationMenuItem[][]> {
  const route = useRoute()
  const router = useRouter()
  const badges = inject(BADGES, ref<MenuBadges>({}))
  const config = application.layouts[layout]
  // A placeholder route without `:item` gets no params, which the router would discard with a warning.
  const placeholderTakesItem = computed(() => {
    const record = config?.placeholder ? router.getRoutes().find(candidate => candidate.name === config.placeholder) : undefined
    return record ? /:item\b/.test(record.path) : true
  })
  return computed(() => buildMenu(layout, menu, {
    active: config ? resolveActiveItem(config, route) : null,
    badges: badges.value,
    placeholderTakesItem: placeholderTakesItem.value,
  }))
}

/**
 * The open sub-menus of one menu, for `UNavigationMenu`'s v-model: on every navigation
 * they become the parents of the active item; the user may open others in between.
 */
export function useOpenMenuItems(layout: string, menu: MenuName, app: ApplicationConfig = application): Ref<string[]> {
  const route = useRoute()
  const config = app.layouts[layout]
  const open = ref<string[]>([])
  watch(
    () => (config ? resolveActiveItem(config, route) : null),
    (id) => {
      open.value = config ? parentsOf(config, menu, id) : []
    },
    { immediate: true },
  )
  return open
}

function toDropdown(item: NavigationMenuItem): DropdownMenuItem {
  const { label, icon, to, onSelect, disabled, type, children, badge } = item
  const result: DropdownMenuItem = { label, icon, to, onSelect, disabled, type: type === 'label' ? 'label' : undefined }
  // The shell renders it in the item's trailing slot: a dropdown item has no badge of its own.
  if (badge !== undefined) result.badge = badge
  if (children?.length) result.children = children.map(child => toDropdown(child as NavigationMenuItem))
  return result
}

/** Menu groups as `UDropdownMenu` items, badges kept. */
export function dropdownMenu(groups: NavigationMenuItem[][]): DropdownMenuItem[][] {
  return groups.map(group => group.map(toDropdown))
}

/** One menu of one layout as `UDropdownMenu` items (the account menu, for example). */
export function useApplicationDropdown(layout: string, menu: MenuName): ComputedRef<DropdownMenuItem[][]> {
  const items = useApplicationMenu(layout, menu)
  return computed(() => dropdownMenu(items.value))
}
